let raw = $input.first().json;
while (raw.body && typeof raw.body === "object") { raw = raw.body; }

// ── Helpers ──────────────────────────────────────────────────────────────────
const getPropValue = (p) => {
  if (!p) return "";
  if (typeof p === "string") return p;
  if (p.url) return p.url;
  if (p.email) return p.email;
  if (p.rich_text && p.rich_text[0]) return p.rich_text[0].plain_text || p.rich_text[0].text?.content || "";
  if (p.title && p.title[0]) return p.title[0].plain_text || p.title[0].text?.content || "";
  return "";
};

const props = raw.properties || {};

// ── Transcripción ─────────────────────────────────────────────────────────────
// Nuevo formato: campo "transcription" (inglés) llega directo en el body
// Formato viejo Notion: raw.transcripcion o raw.body.transcripcion
const transcripcion = raw.transcription || raw.transcripcion || "";

// ── Link al Doc / fileId ──────────────────────────────────────────────────────
// Nuevo formato: "docUrl"
// Formato viejo Notion: "Link a discovery" en properties
let linkDiscovery = raw.docUrl || "";

if (!linkDiscovery) {
  for (const [k, v] of Object.entries(props)) {
    if (!v) continue;
    const kNorm = k.toLowerCase();
    if (kNorm.includes("discovery") || kNorm.includes("transcri") || kNorm.includes("drive") || kNorm.includes("doc") || kNorm.includes("link")) {
      const val = getPropValue(v);
      if (val && (val.includes("drive.google.com") || val.includes("docs.google.com"))) {
        linkDiscovery = val;
        break;
      }
    }
  }
}
if (!linkDiscovery) {
  for (const [k, v] of Object.entries(raw)) {
    if (typeof v === "string" && (v.includes("drive.google.com") || v.includes("docs.google.com"))) {
      linkDiscovery = v;
      break;
    }
  }
}

let fileId = "";
const match = (linkDiscovery || "").match(/\/(?:d|document\/d)\/([a-zA-Z0-9_-]+)/) || (linkDiscovery || "").match(/id=([a-zA-Z0-9_-]+)/);
if (match) fileId = match[1];

// ── Empresa ───────────────────────────────────────────────────────────────────
let empresa = "";
for (const [k, v] of Object.entries(props)) {
  if (!v) continue;
  const kNorm = k.toLowerCase();
  if (kNorm.includes("empresa") || kNorm.includes("name") || kNorm.includes("title") || kNorm.includes("cliente") || kNorm.includes("oportun")) {
    empresa = getPropValue(v);
    if (empresa) break;
  }
}
if (!empresa) empresa = raw.property_nombre_oportunidad || raw.empresa || raw.name || raw.company || "Cliente";

// ── Owner / Comercial ─────────────────────────────────────────────────────────
// Nuevo formato: "ownerEmail" llega directo
let ownerEmail = raw.ownerEmail || raw.owner_email || "";

if (!ownerEmail) {
  let rawOwnerFromProp = Array.isArray(raw.property_owner) ? raw.property_owner[0] : (raw.property_owner || "");
  ownerEmail = raw.owner || rawOwnerFromProp || "";
}
if (!ownerEmail) {
  for (const [k, v] of Object.entries(props)) {
    if (!v) continue;
    const kNorm = k.toLowerCase();
    if (kNorm.includes("owner") || kNorm.includes("responsable") || kNorm.includes("comercial")) {
      if (v.people && v.people[0] && v.people[0].person && v.people[0].person.email) {
        ownerEmail = v.people[0].person.email;
        break;
      }
    }
  }
}
if (!ownerEmail) ownerEmail = "nicolas.gonzalez@xtract.app";

// ── Emails de interlocutores / clientes ───────────────────────────────────────
const notionEmails = [];
for (const [k, v] of Object.entries(props)) {
  if (!v) continue;
  if (v.email) notionEmails.push(v.email);
  if (v.people && Array.isArray(v.people)) {
    v.people.forEach(p => {
      if (p && p.person && p.person.email && !p.person.email.includes("@xtract.app")) {
        notionEmails.push(p.person.email);
      }
    });
  }
  if (k.toLowerCase().includes("mail") || k.toLowerCase().includes("correo") || k.toLowerCase().includes("email")) {
    const val = getPropValue(v);
    if (val && val.includes("@") && !val.includes("@xtract.app")) notionEmails.push(val);
  }
}

// ── URL de Notion ─────────────────────────────────────────────────────────────
const rawId = (raw.id || raw.page_id || "").replace(/-/g, "");
const notionUrl = raw.url || (rawId ? ("https://www.notion.so/" + rawId) : "");

return [{ json: {
  transcripcion,
  fileId,
  linkDiscovery,
  empresa,
  ownerEmail,
  notionUrl,
  notionEmails,
  raw
} }];

// La transcripción ya viene extraída por "Code - Extraer Datos"
// (ya sea del campo "transcription" del nuevo payload o de la card de Notion)
const extraidos = $('Code - Extraer Datos').first().json;
let txt = String(extraidos.transcripcion || '').trim();
if (txt.length > 22000) {
  txt = txt.slice(0, 22000) + '\n...[transcripción resumida]';
}
return [{ json: { transcripcion: txt } }];

