// 1. Entradas y Datos Base
const iaRaw = $input.first().json;
const ia = iaRaw.output || iaRaw;

let extraidos = {};
try {
  extraidos = $("Code - Extraer Datos").first().json || {};
} catch(e) {}

let notion = {};
try {
  notion = $("Notion - Traer card completa").first().json || {};
} catch(e) {}

// Destinatario Forzado ("U0BJLTDCAMR" para pruebas)
const FORZAR_DESTINATARIO = "";

const idioma = (ia.idioma === "pt") ? "pt" : "es";
const esPt = idioma === "pt";

// Normalizar asteriscos a simples de Slack (*texto*)
const toSlackBold = str => String(str || "")
  .replace(/\*{2,}([^*]+)\*{2,}/g, "*$1*")
  .replace(/\*{2,}/g, "*");

// Extraer empresa limpiamente priorizando lo normalizado
const empresa = (extraidos.empresa || notion.empresa || notion.Empresa || notion.name || notion.title || notion.Name || "").trim() || (esPt ? "sua empresa" : "su empresa");

const emails = (extraidos.notionEmails && extraidos.notionEmails.length) 
  ? extraidos.notionEmails 
  : (Array.isArray(ia.emails_destinatarios) ? ia.emails_destinatarios.filter(Boolean) : []);
const paraTexto = emails.length ? emails.join(", ") : "*(Completar emails de los interlocutores)*";

let defaultSubject = esPt ? "Acompanhamento - Automatização de Contas a Pagar" : "Resumen de la reunión y próximos pasos";
const subjectPersonalizado = ia.asunto_email || defaultSubject;

// 2. Nombre del Comercial (SOLO PRIMER NOMBRE, sin apellido)
const interlocutores = (ia.interlocutores || extraidos.interlocutor || extraidos.nombreKdm || notion.persona || (esPt ? "equipe" : "equipo")).trim();
const rawOwner = extraidos.ownerEmail || (Array.isArray(notion.owner) ? notion.owner[0] : notion.owner) || notion.ownerEmail || "nicolas.gonzalez@xtract.app";

const OWNER_NOMBRES = {
  "nicolas.gonzalez@xtract.app": "Nicolás",
  "wenceslao.hoepner@xtract.app": "Wenceslao",
  "damian.deggeller@xtract.app": "Damián",
  "greta.bruno@xtract.app": "Greta",
  "ian.brandan@xtract.app": "Ian",
  "tomas.marconi@xtract.app": "Tomás",
  "juan.alvarez@xtract.app": "Juan",
  "matias.febre@xtract.app": "Matías",
  "jesus.degruttola@xtract.app": "Jesús"
};
const ownerKey = String(rawOwner || "").toLowerCase().trim();
const ownerLocal = rawOwner.split("@")[0].replace(/[._-]+/g, " ");
const primerNombreComercial = OWNER_NOMBRES[ownerKey] || (ownerLocal ? (ownerLocal.split(" ")[0].charAt(0).toUpperCase() + ownerLocal.split(" ")[0].slice(1).toLowerCase()) : "Nicolás");

// 3. Construir Bloques del Correo con el estilo exacto de Nicolás (con subtítulos en negrita)

// Saludo y agradecimiento
let saludo = "";
if (ia.saludo_intro) {
  saludo = ia.saludo_intro
    .replace(/(?:less+)?compartos+uns+breves+resumen[^.\n]*[:.\n]?/gi, "")
    .replace(/compartilhos+ums+breves+resumo[^.\n]*[:.\n]?/gi, "")
    .replace(/\b(?:les|comparto|compartilho)\s*$/gi, "")
    .trim();
} else {
  if (esPt) {
    saludo = "Olá " + interlocutores + ", boa tarde.\n\nMuito obrigado pelo tempo na nossa conversa de hoje.";
  } else {
    saludo = "Hola " + interlocutores + ", buenas tardes.\n\nMuchas gracias por el tiempo en la reunión de hoy.";
  }
}

const fraseIntro = esPt 
  ? "Compartilho um breve resumo do que conversamos e os próximos passos:"
  : "Les comparto un breve resumen de lo conversado y los próximos pasos:";

// Resumen de puntos principales (Situación actual)
let listaPuntos = [];
if (Array.isArray(ia.desafios_puntos)) {
  for (const item of ia.desafios_puntos) {
    const s = String(item || "").trim();
    if (s.includes("•") || (s.includes("-") && s.length > 50)) {
      const splitItems = s.split(/[•\n]+/).map(x => x.trim()).filter(x => x.length > 5);
      listaPuntos.push(...splitItems);
    } else if (s) {
      listaPuntos.push(s);
    }
  }
} else if (typeof ia.desafios_puntos === "string" && ia.desafios_puntos.trim()) {
  listaPuntos = ia.desafios_puntos.split(/[•\n]+/).map(x => x.trim()).filter(x => x.length > 5);
} else if (ia.desafio) {
  listaPuntos = String(ia.desafio).split(/[•\n]+/).map(x => x.trim()).filter(x => x.length > 5);
}

// Asegurar negritas en puntos clave si la IA no las puso
const autoBoldPunto = str => {
  let res = String(str || "").trim();
  if (!res.includes('*')) {
    res = res.replace(/(\b\d{2,4}(?:[–\-]\d{2,4})?\s+(?:facturas|documentos|comprobantes)\s+(?:mensuales|por\s+mes)?)/gi, '*$1*');
    res = res.replace(/(correo,?\s*WhatsApp,?\s*formato físico[^.,]*portales de proveedores)/gi, '*$1*');
    res = res.replace(/(facturas con Orden de Compra y compras directas)/gi, '*$1*');
    res = res.replace(/(picos de trabajo durante el cierre y comienzo de cada mes)/gi, '*$1*');
  }
  return toSlackBold(res);
};

const puntosFinales = listaPuntos.slice(0, 4);
const bloquePuntos = puntosFinales.length 
  ? puntosFinales.map(p => "\t•  " + autoBoldPunto(String(p).replace(/^[•\-\*]\s*/, "").trim())).join("\n") 
  : (esPt ? "\t•  Automatização do fluxo de entrada de *notas fiscais*." : "\t•  Automatización del flujo de *facturas*.");

const tituloSituacion = esPt ? "*Situação atual*" : "*Situación actual*";
const seccionSituacion = tituloSituacion + "\n" + bloquePuntos;

// Propuesta de solución (Objetivo)
let rawSolucion = ia.solucion_encaje || ia.solucion || "";
rawSolucion = rawSolucion.replace(/\n{3,}/g, "\n\n").trim();
if (!rawSolucion.includes('*')) {
  rawSolucion = rawSolucion
    .replace(/(lectura, imputación y registración)/gi, '*$1*')
    .replace(/(contabilização automática)/gi, '*$1*')
    .replace(/(integração via API)/gi, '*$1*');
}
rawSolucion = toSlackBold(rawSolucion);
const tituloObjetivo = esPt ? "*Objetivo*" : "*Objetivo*";
const seccionObjetivo = rawSolucion ? (tituloObjetivo + "\n" + rawSolucion) : "";

// Documentación de API (si aplica)
const solicitoApi = ia.solicito_documentacion_api === true || ia.solicito_documentacion_api === "true";
let bloqueApi = "";
if (solicitoApi) {
  if (esPt) {
    bloqueApi = "Conforme combinamos, compartilho a <https://xtractapi.docs.apiary.io/#reference|documentação da nossa API REST> para validação com o suporte do ERP.";
  } else {
    bloqueApi = "Tal como acordamos, les comparto la <https://xtractapi.docs.apiary.io/#reference|documentación de la API Rest> para que el equipo técnico valide los endpoints.";
  }
}

// Próximos pasos
const reunionAgendada = ia.reunion_ya_agendada === true || ia.reunion_ya_agendada === "true" || (ia.detalle_reunion_agendada && !ia.detalle_reunion_agendada.toLowerCase().includes("pendiente"));
let defaultProximos = "";
if (reunionAgendada) {
  const det = ia.detalle_reunion_agendada || (esPt ? "na data combinada" : "el jueves a la misma hora");
  defaultProximos = esPt 
    ? "Como combinamos, nos reunimos novamente *" + det.replace(/\*/g, "") + "* para realizar a *demonstração da Xtract* e apresentar a *proposta comercial, escopo e prazos de implementação*.\nEnvio o convite para deixar agendado."
    : "Como coordinamos, nos reunimos nuevamente *" + det.replace(/^el\s+/i, "el ").replace(/\*/g, "") + "* para realizar la *demostración de Xtract* y presentarles la *propuesta comercial, alcance y tiempos estimados de implementación*.\nLes envío la invitación para dejarlo agendado.";
} else {
  defaultProximos = esPt 
    ? "Como próximo passo, coordenamos uma reunião de 30 minutos na próxima semana para realizar a *demonstração da ferramenta de ponta a ponta* e apresentar a *proposta comercial* adaptada à sua operação."
    : "Como próximo paso, coordinemos una videollamada de 30 minutos la próxima semana para realizar la *demostración de la herramienta de punta a punta* y presentarles la *propuesta comercial* adaptada a su operación.";
}

let rawProximos = ia.proximos_pasos || defaultProximos;
rawProximos = rawProximos
  .replace(/te env[íi]o por whatsapp[^.\n]*[.\n]?/gi, "")
  .replace(/le enviar[ée] por correo la documentaci[oó]n[^.\n]*[.\n]?/gi, "")
  .replace(/le env[íi]o por email la documentaci[oó]n[^.\n]*[.\n]?/gi, "")
  .replace(/enviaremos la documentaci[oó]n[^.\n]*[.\n]?/gi, "")
  .replace(/envio por e-?mail a documenta[çc][aã]o[^.\n]*[.\n]?/gi, "")
  .replace(/whatsapp/gi, "correo")
  .trim();

if (!rawProximos.includes('*')) {
  rawProximos = rawProximos
    .replace(/(demostración de Xtract|demonstração da Xtract)/gi, '*$1*')
    .replace(/(propuesta comercial, alcance y tiempos estimados de implementación|proposta comercial, escopo e prazos de implementação)/gi, '*$1*');
}
rawProximos = toSlackBold(rawProximos);

const tituloProximos = esPt ? "*Próximo passo*" : "*Próximo paso*";
const seccionProximos = tituloProximos + "\n" + (rawProximos || defaultProximos);

// Casos de Éxito oficiales (con sangría tabulada y enlaces formateados)
const normText = s => String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
let erpResuelto = {};
try { erpResuelto = $("Resolver ERP").first().json || {}; } catch(e) {}
const erpNorm = normText(erpResuelto.erp || "");
const empresaNorm = normText(empresa);

let videosRelevantes = [];
if (esPt) {
  if (erpNorm.includes("sap")) {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=yJtHFuTnwSA|Caso de sucesso Pomelo (SAP)>");
  } else {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=k2uYl5kSGBQ|Caso de sucesso MODO>");
  }
} else {
  if (erpNorm.includes("netsuite")) {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=4xFCkoxat1o|Caso InvGate (NetSuite)>");
  } else if (erpNorm.includes("sap")) {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=ikDLA5HjQbs|Caso Pomelo (SAP)>");
  } else if (empresaNorm.includes("salud") || empresaNorm.includes("sanatorio") || empresaNorm.includes("clinica") || empresaNorm.includes("hospital")) {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=I8J-vd5U5ck|Caso SanCor Salud>");
  } else {
    videosRelevantes.push("\t•  <https://www.youtube.com/watch?v=k2uYl5kSGBQ|Caso MODO>");
  }
}
const bloqueCasosExito = videosRelevantes.join("\n");

// Cierre y firma prolija (sin duplicar nombres)
let bloqueCierre = "";
if (esPt) {
  let despedidaPt = (ia.cierre_despedida || "Fico à disposição.")
    .replace(/muito obrigado[^.\n]*/gi, "")
    .replace(/abra[çc]os[^.\n]*/gi, "")
    .replace(new RegExp(primerNombreComercial, "gi"), "")
    .trim();
  if (!despedidaPt) despedidaPt = "Fico à disposição.";
  bloqueCierre = despedidaPt + "\n\nMuito obrigado e abraços,\n" + primerNombreComercial;
} else {
  let despedidaEs = (ia.cierre_despedida || "Quedo atento.")
    .replace(/saludos[^.\n]*/gi, "")
    .replace(/muchas gracias[^.\n]*/gi, "")
    .replace(/gracias[^.\n]*/gi, "")
    .replace(new RegExp(primerNombreComercial, "gi"), "")
    .trim();
  if (!despedidaEs) despedidaEs = "Quedo atento.";
  bloqueCierre = despedidaEs + "\n\nSaludos y gracias,\n" + primerNombreComercial;
}

// 4. Ensamble del Borrador Completo
const trimNewlines = str => String(str || "").replace(/^\n+|\n+$/g, "");

const cuerpoEmail = [
  saludo,
  fraseIntro,
  seccionSituacion,
  seccionObjetivo,
  bloqueApi,
  seccionProximos,
  bloqueCasosExito,
  bloqueCierre
].map(trimNewlines).filter(Boolean).join("\n\n");

// 5. Matching en Cascada para encontrar el ID de Slack del Comercial
const norm = s => String(s == null ? "" : s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
const emailNorm = norm(rawOwner);
const local = norm(rawOwner.split("@")[0]);
const comoNombre = local.replace(/[._-]+/g, " ");

const KNOWN_OWNERS = {
  // Principales Ejecutivos
  'nicolas.gonzalez@xtract.app': 'U02MCAHHM1T',
  'nicolas@xtract.app': 'U02MCAHHM1T',
  'nicolas gonzalez': 'U02MCAHHM1T',
  'nicolás gonzalez': 'U02MCAHHM1T',
  'tomas@xtract.app': 'U01AC8ARHG8',
  'tomas.marconi@xtract.app': 'U01AC8ARHG8',
  'tomas marconi': 'U01AC8ARHG8',
  'wenceslao.hoepner@xtract.app': 'U0BBASA0F60',
  'wenceslao@xtract.app': 'U0BBASA0F60',
  'wenceslao hoepner': 'U0BBASA0F60',
  'juan.alvarez@xtract.app': 'U094FGA9VEF',
  'juan@xtract.app': 'U094FGA9VEF',
  'juan alvarez': 'U094FGA9VEF',
  'damian.deggeller@xtract.app': 'U09PYEWUHGF',
  'damian@xtract.app': 'U09PYEWUHGF',
  'damian deggeller': 'U09PYEWUHGF',
  'damián deggeller': 'U09PYEWUHGF',
  'greta.bruno@xtract.app': 'U096BLX5864',
  'greta@xtract.app': 'U096BLX5864',
  'greta bruno': 'U096BLX5864',
  'ian.brandan@xtract.app': 'U09FZ5MLF0E',
  'ian@xtract.app': 'U09FZ5MLF0E',
  'ian brandan': 'U09FZ5MLF0E',

  // Equipo Comercial Ampliado & SDRs
  'jesus@xtract.app': 'U01A12169ND',
  'jesus.degruttola@xtract.app': 'U01A12169ND',
  'jesús de gruttola': 'U01A12169ND',
  'jesus.soria@xtract.app': 'U0AM7HGHQTB',
  'jesús soria': 'U0AM7HGHQTB',
  'matias.febre@xtract.app': 'U07JW0A2AL9',
  'matias@xtract.app': 'U07JW0A2AL9',
  'matías febré': 'U07JW0A2AL9',
  'neiber@xtract.app': 'U06R7TRQKV1',
  'neiber monti': 'U06R7TRQKV1',
  'gaston.moriconi@xtract.app': 'U093XP1LAUC',
  'gastón moriconi': 'U093XP1LAUC',
  'bruno.corrao@xtract.app': 'U064UNXJZ7F',
  'franco.argibel@xtract.app': 'U08BMGJDT7F',
  'santiago.paredes@xtract.app': 'U0AQMAM2ZB9',
  'alejandro@xtract.app': 'U01A11YN7SM',
  'alejandro.bezdjian@xtract.app': 'U01A11YN7SM',
  'ezequiel.nievas@xtract.app': 'U09CY8PBPSN',
  'sofia.ferro@xtract.app': 'U0BE9AQHFPV'
};

let usuarios = [];
try {
  const raw = $("Slack - Traer usuarios").first().json;
  usuarios = (raw.members || raw.users || []).filter(u => u && u.id && !u.deleted && !u.is_bot);
} catch(e) {}

const perfil = u => u.profile || {};
let owner = usuarios.find(u => norm(perfil(u).email) === emailNorm) || null;
if (!owner) owner = usuarios.find(u => norm(u.name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).display_name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(u.real_name) === comoNombre) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).real_name) === comoNombre) || null;

const SLACK_FALLBACK_DM = "U0BJLTDCAMR";
const ownerSlackIdReal = owner ? owner.id : (KNOWN_OWNERS[emailNorm] || SLACK_FALLBACK_DM);
const ownerSlackId = FORZAR_DESTINATARIO || ownerSlackIdReal;
const enModoPrueba = !!FORZAR_DESTINATARIO;
const esFallback = !owner && !KNOWN_OWNERS[emailNorm];

// Link a Notion y Link a Discovery
const rawId = (extraidos.notionUrl ? "" : (notion.id || notion.page_id || "").replace(/-/g, ""));
const notionUrl = extraidos.notionUrl || notion.url || (rawId ? ("https://www.notion.so/" + rawId) : "");
const linkDoc = extraidos.linkDiscovery || "";

// 6. Mensaje Formateado para Slack
const tagIdioma = esPt ? " 🇧🇷 *(Português)*" : " 🌎 *(Español)*";
const footerCopia = esPt ? "_Pronto para copiar e enviar no Gmail / Outlook._" : "_Listo para copiar y enviar en Gmail / Outlook._";

const linksEncabezado = linkDoc ? ("• <" + linkDoc + "|Abrir Transcripción en Google Docs>") : "";

const textoSlack = [
  (enModoPrueba ? (":test_tube: *MODO PRUEBA* — en producción esto le hubiera llegado a `" + ownerSlackIdReal + "`") : ""),
  ":incoming_envelope: *Borrador de Email Post-Discovery*" + tagIdioma + " — " + empresa,
  (ia.reunion_ya_agendada ? "📅 *Reunión pactada:* " + (ia.detalle_reunion_agendada || "Sí (en la llamada)") : "📅 *Reunión:* Pendiente de coordinar"),
  linksEncabezado,
  (esFallback ? "_Nota: Enviado a fallback de pruebas._" : ""),
  (erpResuelto.erp_sin_match ? "⚠️ *ERP sin confirmar:* el cliente mencionó algo como \"" + erpResuelto.erp_sin_match + "\", pero no coincide con ninguna opción del listado de Notion — completar el campo 'Que sistema usan?' manualmente." : ""),
  "",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "*Para:* " + paraTexto,
  "*Subject:* " + subjectPersonalizado,
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "",
  cuerpoEmail,
  "",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  footerCopia
].filter(Boolean).join("\n");

return [{ json: {
  texto_slack: textoSlack,
  cuerpo_email: cuerpoEmail,
  idioma: idioma,
  para: paraTexto,
  subject: subjectPersonalizado,
  owner_slack_id: ownerSlackId,
  comercial: primerNombreComercial,
  empresa: empresa,
  notion_url: notionUrl
} }];

// =====================================================================
// RESOLVER ERP: prioridad campo manual de Notion > lo dicho en la llamada.
// El campo manual de Notion ("Que sistema usan?(*)") ya sale de la lista
// desplegable real -> si esta cargado, es la fuente de verdad y no necesita
// matching. Si no esta cargado, se toma lo que la IA extrajo de la
// transcripcion (erp_llamada) y se lo compara contra el listado REAL y VIVO
// de opciones de Notion (Notion - Traer lista ERP), porque Fathom transcribe
// pesimo los nombres de ERP (ver comentario del mismo problema en WF05:
// "Finnegans" salio como Finance, Finex, Fan, Finegan y Fin en una sola
// llamada). Si no matchea ninguna opcion real, NO se inventa nada: queda
// generico y se avisa en el mensaje de Slack para que lo revise un humano.
// =====================================================================
const PROP_ERP = "Que sistema usan?(*)";

const normERP = s => String(s || "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, " ")
  .trim();

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  const fila = Array(n + 1).fill(0).map((_, i) => i);
  for (let i = 1; i <= m; i++) {
    let prevDiag = fila[0];
    fila[0] = i;
    for (let j = 1; j <= n; j++) {
      const tmp = fila[j];
      fila[j] = a[i - 1] === b[j - 1] ? prevDiag : 1 + Math.min(prevDiag, fila[j], fila[j - 1]);
      prevDiag = tmp;
    }
  }
  return fila[n];
}

function matchearContraLista(valor, lista) {
  const v = normERP(valor);
  if (!v || !lista.length) return null;
  let hit = lista.find(op => normERP(op) === v);
  if (hit) return hit;
  hit = lista.find(op => {
    const o = normERP(op);
    return o.length > 2 && (o.includes(v) || v.includes(o));
  });
  if (hit) return hit;
  hit = lista.find(op => {
    const o = normERP(op);
    const dist = levenshtein(v, o);
    return dist <= Math.max(1, Math.ceil(Math.min(v.length, o.length) * 0.3));
  });
  return hit || null;
}

// 1. Listado canonico vivo desde Notion
let listaCanonica = [];
try {
  const db = $("Notion - Traer lista ERP").first().json || {};
  const prop = (db.properties || {})[PROP_ERP] || {};
  const opciones = (prop.select && prop.select.options) || [];
  listaCanonica = opciones.map(o => o.name).filter(Boolean);
} catch (e) {}

// 2. Valor manual ya cargado en la card de Notion (prioridad 1)
let erpNotionManual = "";
let pageId = "";
try {
  const card = $("Notion - Traer card completa").first().json || {};
  pageId = card.id || "";
  const prop = (card.properties || {})[PROP_ERP] || {};
  erpNotionManual = (prop.select && prop.select.name) || "";
} catch (e) {}

if (!pageId) {
  try {
    const extraidos = $("Code - Extraer Datos").first().json || {};
    pageId = (extraidos.raw && extraidos.raw.id) || extraidos.pageId || (extraidos.notionUrl || "").split("/").pop().replace(/-/g, "") || "";
  } catch (e) {}
}

// 3. ERP mencionado en la llamada (IA), solo si Notion no lo tiene cargado
let erpLlamada = "";
try {
  const iaRaw = $("IA - Redactar borrador de correo").first().json || {};
  const ia = iaRaw.output || iaRaw;
  erpLlamada = (ia.erp_llamada || "").toString().trim();
} catch (e) {}

let erp = "";
let erpConfirmado = false;
let erpSinMatch = "";
let debeActualizarNotion = false;

if (erpNotionManual) {
  erp = erpNotionManual;
  erpConfirmado = true;
  debeActualizarNotion = false; // Ya esta cargado en Notion, no pisar
} else if (erpLlamada) {
  const matched = matchearContraLista(erpLlamada, listaCanonica);
  if (matched) {
    erp = matched;
    erpConfirmado = true;
    debeActualizarNotion = true; // Solo actualiza si hizo match exacto con listaCanonica
  } else {
    erpSinMatch = erpLlamada;
  }
}

return [{ json: {
  erp,
  erp_confirmado: erpConfirmado,
  erp_sin_match: erpSinMatch,
  erp_lista_canonica: listaCanonica,
  debe_actualizar_notion: debeActualizarNotion,
  page_id: pageId
} }];

